package com.wipro.spring; import java.util.List; import java.util.Map; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.ui.Model; import org.springframework.jdbc.core.JdbcTemplate; @Controller public class StudentController { private final JdbcTemplate jdbc; public StudentController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping("/") public String students(Model model){List<Map<String,Object>> students=jdbc.queryForList("SELECT STUDENT_ID,STUDENT_NAME,EMAIL FROM STUDENT");model.addAttribute("students",students);return "students";} }